# Summary
- If debug=true, unauthorized on XmlView fails to render.
- Works for default View / ctp. Works for JsonView.

Result when debug=false

``` xml
<response>
<message>Unauthorized</message>
<url>/api/exports/manufacturers.xml</url>
<code>401</code>
</response>
```
## Example Requests
- If logged in all 3 requests render just fine
- If not logged in, however, only regular (standard view / ctp) and json render, xml throws an error
- URLs
  - http://devicesdbservices.dev/api/search/manufacturers
  - http://devicesdbservices.dev/api/search/manufacturers.json
  - http://devicesdbservices.dev/api/search/manufacturers.xml // error if not logged in
## Setup

``` php
// routes
Router::prefix('Api', function($routes) {
    $routes->extensions(['json', 'xml']);
    $routes->connect('/', ['controller' => 'Exports' , 'action' => 'index']);
    $routes->scope('/exports', ['controller' => 'Exports'], function ($routes) {
        $routes->addExtensions(['csv']);
        $routes->connect('/:action', ['controller' => 'Exports']);
    });
    $routes->fallbacks('DashedRoute');
});

// AppController
<?php
namespace App\Controller\Api;

use App\Controller\AppController;
use Cake\Event\Event;
use Cake\Network\Exception\MethodNotAllowedException;

/**
 * Api Application Controller
 *
 */
class ApiAppController extends AppController
{

    /**
     * Initialization hook method.
     *
     * Use this method to add common initialization code like loading components.
     *
     * @return void
     */
    public function initialize()
    {
        $this->loadComponent('RequestHandler');
        $this->loadComponent('Security', [
            'blackHoleCallback' => 'forceSSL',
        ]);
        $this->loadComponent('Auth', [
            'authenticate' => [
                'Basic' => [
                    'realm' => \Cake\Core\Configure::read('Settings.AppTitle'),
                    'userModel' => 'ApiUsers',
                    'scope' => ['ApiUsers.is_active' => 1],
                ],
            ],
            'storage' => 'Memory',
        ]);
    }

    /**
     * Checks for web interface access; utilized by CakePHP Auth Component
     *
     * @return true|false
     */
    public function isAuthorized($user = null)
    {
        return false;
    }

    /**
     * beforeFilter hook method.
     *
     * Use this method to do pre-processing before any action is executed.
     *
     * @return void
     * @throws \Cake\Network\Exception\MethodNotAllowedException
     */
    public function beforeFilter(Event $event)
    {
        $this->viewBuilder()->layout('api');
        if ($this->request->is('get') === false) {
            throw new MethodNotAllowedException('Invalid HTTP method. Use http GET instead.');
        }
    }

    /**
     * helper method executed by CAKEPHP Security component to throw when SSL is not being used.
     *
     * @throws Cake\Network\Exception\ForbiddenException;
     * @return void
     */
    public function forceSSL()
    {
        throw new ForbiddenException('HTTP not allowed. Use HTTPS instead.');
    }

}


